import "server-only";
import type { Competency, QuestionKind, RoleId } from "@/lib/constants";

/** 1 = fundamentals, 2 = intermediate, 3 = advanced / senior. */
export type Tier = 1 | 2 | 3;

export interface BankQuestion {
  id: string;
  kind: QuestionKind;
  tier: Tier;
  competency: Competency;
  text: string;
  /** Concept groups an interviewer listens for; any synonym in a group counts. */
  keywords: string[][];
  /** Model answer shown in demo-mode feedback. */
  ideal: string;
}

type Entry = [id: string, tier: Tier, competency: Competency, text: string, keywords: string[], ideal: string];

const build = (kind: QuestionKind) => (entries: Entry[]): BankQuestion[] =>
  entries.map(([id, tier, competency, text, keywords, ideal]) => ({
    id,
    kind,
    tier,
    competency,
    text,
    keywords: keywords.map((group) => group.split("|")),
    ideal,
  }));

const technical = build("technical");
const behavioral = build("behavioral");

type RoleBank = { technical: BankQuestion[]; behavioral: BankQuestion[] };

